    "question": "次は、精神物理学（心理物理学）に関する記述であるが、A～Eに当てはまるものの組合せとして最も妥当なのはどれか。\n\n感覚に関する経験則の一つであるウェーバーの法則は、［A］と、基準となる刺激の強度との間に一定の関係があることを示したものである。例えば、300gの粉末を手に乗せ、1gずつ粉末を増やしたところ、10g追加した時に初めて重さの違いを感じたとする。同一条件下で、最初の粉末の重さが3,000gだった場合、同じように重さの違いが初めて感じられるには、［B］の粉末を追加する必要がある。この関係を式で表すと、\nK＝［C］\nとなる。この式において、Sは基準となる刺激強度、ΔSは［A］の大きさ、Kは定数を表すものとする。定数Kの値が［D］ほど、刺激のわずかな変化に対して感度が高いことを意味する。定数Kは、感覚の［E］によって異なることが知られている。",
