    "difficulty": 3,
    "question": "次の記述のA～Eに当てはまるものの組合せとして最も妥当なのはどれか。\n\nIn ［A］ conditioning the organism learns to associate new stimuli with natural, biological responses such as salivation or fear. The organism does not learn something new but rather begins to perform in an existing behavior in the presence of a new signal. Operant conditioning, on the other hand, is learning that occurs based on the consequences of ［B］ and can involve the learning of new actions. 《中略》\n\nPsychologist Edward L. Thorndike (1874-1949) was the first scientist to systematically study operant conditioning. In his research Thorndike (1898) observed cats who had been placed in a “puzzle box” from which they tried to escape. At first the cats scratched, bit, and swatted haphazardly, without any idea of how to get out. But eventually, and accidentally, they pressed the lever that opened the door and exited to their prize, a scrap of fish. The next time the cat was constrained within the box it attempted fewer of the ［C］ responses before carrying out the successful escape, and after several trials the cat learned to almost immediately make the correct response.\n\nObserving these changes in the cats' behavior led Thorndike to develop his law of effect, the principle that responses that create a typically pleasant outcome in a particular situation are ［D］ likely to occur again in a similar situation, whereas responses that produce a typically unpleasant outcome are ［E］ likely to occur again in the situation (Thorndike, 1911).",
