      "イ": "気分に合う方向に満足度の判断が動くためAは気分一致効果で、連合ネットワークは活性化拡散を用いて説明できる。天気に注意すると気分を天気のためと考え、人生全体の評価に使わず差が消えるという感情情報機能説に合う。",
      "ウ": "気分の良い日に生活満足度が高いという最初の結果は気分一致に当たる。天気に注意を向けた条件では、差は向きが変わったのではなく消失した。",
