    "difficulty": 3,
    "question": "感情や情動に係る諸理論に関する記述ア～エのうち、妥当なもののみを挙げているのはどれか。\n\nア．情動のジェームズ＝ランゲ説は、刺激や状況によって生じる末梢活動の変化が情動経験の起源になることを主張する説である。この説が主張された後、情動における顔の役割を重視したS. S. トムキンスは、顔面筋肉運動の感覚フィードバックが、生理的反応のフィードバックと同じように情動経験を生じさせるとする、顔面フィードバック仮説を提唱した。\n\nイ．J. P. フォーガスの感情混入モデルによれば、社会的判断には4種類の情報処理方略があり、特定の感情からの影響は、4種類の処理方略のうちどれが採用されるかによって異なるとされる。直接アクセス処理と動機充足処理は感情の混入が少ない方略であるのに対し、ヒューリスティック処理と実質的処理は感情の混入を大きく受ける方略である。\n\nウ．H. セリエは、多様なストレッサーによる生体の非特異的な防衛反応を発見し、汎適応症候群という概念を発表した。この汎適応症候群の考えに基づけば、ストレッサーによる生理的覚醒と課題成績とが逆U字型の関係になる。セリエによると、ストレッサーに対する生体の非特異的反応は、ストレッサーに対する認知的評価と、ストレッサーに対する対処行動により異なるという。\n\nエ．J. J. グロスは、感情生起の過程をプロセスモデルとしてまとめた。この過程は、感情を喚起するような刺激に出くわし、その刺激に注意を向け、それを評価し、感情反応が出現するという経緯をたどる。さらにグロスは、このプロセスモデルに依拠して感情制御のモーダルモデルを提唱した。これは、感情生起の各段階に、準備、あたため、ひらめき、検証という四つの異なる感情制御を想定するものである。",
