      "イ": "アは情動経験に先立つ身体反応の役割を述べている。ウの逆U字型は、覚醒水準と作業成績の関係を扱うヤーキーズ・ドッドソンの法則と結び付く。",
      "ウ": "イで感情の混入が少ないとされるのは、既存の判断を取り出す場合や特定の結論を目指す場合である。ウの認知的評価と対処を中心とする説明はラザルスらのストレス理論に近い。",
