    "difficulty": 3,
    "question": "養育者と子どもについての実験や理論に関する記述A～Dのうち、妥当なもののみを全て挙げているのはどれか。\n\nA．ストレンジ・シチュエーション法で回避型に分類された子どもは、養育者との分離や再会場面で何がしたいのかが読み取りづらく、矛盾した行動を見せるタイプである。回避型の子どもの養育者は、子どもがくっつこうとしたときに、その行動に応答するときもあれば応答しないときもあり、子どもは愛着行動を最小限に抑え込むことで、養育者との距離をある範囲にとどめておこうとする。\n\nB．子どもは、愛着対象である養育者等との相互作用を通じて、その対象が特定の場面でどの程度応答してくれるのか、利用可能なのかに関する、自分なりの予見又は仮説である愛着の内的作業モデルを構築していく。J. ボウルビィによると、発達早期に構築されたこの内的作業モデルは、友人関係や恋愛関係など他の対人関係一般に適用され、個人のその後の人生における対人関係スタイルやパーソナリティを持続的に支える機能を果たす。\n\nC．乳児は、生後2、3か月頃から養育者の目や身体の動きに合わせて、養育者と同じ対象に目を向けることができるようになる。生後半年が経つと、養育者と同じ対象を見るだけではなく、養育者が自分と同じように対象に注意を向けていることを理解している状態になり、お互いに対象についての心内状態を伝え合うこともある。これを共同注意と呼ぶ。共同注意が成立することによって、子どもと養育者の二項関係（二者関係）が形成される。\n\nD．20世紀初頭、孤児院や乳児院といった施設に入った子どもは、死亡する割合が高く、また心身の発達に遅れが見られがちであった。J. ボウルビィは、その原因を栄養的問題や医学的管理にあると考え、マターナル・デプリベーションの名で研究した。その後、R. A. スピッツは、マターナル・デプリベーションの研究を発展させてホスピタリズムの概念を体系化した。",
