    "difficulty": 3,
    "question": "次は、因子分析に関する記述であるが、A～Eに当てはまるものの組合せとして最も妥当なのはどれか。\n\n因子分析とは、複数の観測変数間の［A］関係を、それらより少数の因子（潜在変数ともいう）を仮定することで説明しようとする、多変量解析法の一つである。例えば、p個の観測変数（x）に対して、一つの因子のみを考えたとき、それぞれの観測変数は、\n\nxⱼ＝βⱼf＋εⱼ（j＝1,2,…,p）……(1)\n\nと表現される。このとき、因子fにかかる係数βⱼは、それぞれの観測変数が当該因子をどの程度反映しているかを示し、［B］と呼ばれる。また、εⱼは、因子fによって説明されない変数xⱼに固有の成分である。［B］の2乗和によって観測変数における共通性が求められ、一般的に1から共通性を引いた値が［C］となる。また、上記の(1)式が妥当なモデル、すなわちp個の観測変数が1因子モデルによって説明されるということは、εⱼ間が［D］ことを仮定することと同義となる。\n\n因子分析では、二つ以上の因子を仮定することも多い。このときには、単純構造になるように因子軸の回転を行うことで、因子の解釈が容易になるようにする。因子軸の回転は、因子どうしを互いに無相関とする直交回転と、因子間の相関を許容する斜交回転に大別される。因子が直交するとき、［B］は因子と観測変数の相関係数である［E］に一致する。",
