    "difficulty": 3,
    "question": "次は、正規分布に従う変数の線形変換に関する記述であるが、A～Eに当てはまるものの組合せとして最も妥当なのはどれか。\n\n平均μₓ、分散σₓ²の正規分布N(μₓ,σₓ²)に従う変数xに、定数cを乗じて、さらに定数dを加えた新しい変数x′＝cx＋dを作成したとする。この新しい変数x′は、正規分布に［A］。この変数x′の分布の平均はcμₓ＋d、分散は［B］と記述できる。\nある変数の平均と標準偏差を特定の値にそろえる操作を［C］と呼ぶ。平均x̄、標準偏差sₓの学力テストの得点Xを、平均が0、標準偏差が1になるように［C］するためには、観測された学力テストの得点Xに［D］を乗じて、さらに［E］を減じればよい。",
