      "ウ": "外挿は観測した範囲の外について値を推定する操作である。ここでは平均とばらつきの尺度をそろえるため、標準偏差で割って標準化する。",
      "エ": "DとEを使うと(X−x̄)/sₓになる点は正しい。分散にはcの二乗が掛かり、c≠0のとき正規分布の形は保たれる。",
      "オ": "分散は平均からの距離を二乗して求めるので、倍率はcではなくc²になる。また、得点を1/sₓ倍した後に引く量も、元の平均x̄を同じ倍率で変換したx̄/sₓである。"
