    "question": "初期の社会学の理論に関する記述ア～エのうち、妥当なもののみを全て挙げているのはどれか。\n\nア．A. スミスは、社会の規則性の基礎を「模倣」という現象に求めた。社会現象は個人の間の心的相互作用によって起こると考え、少数者の創造的な発明が模倣・反復され、規則性を与えられることで社会が成立するとした。また、模倣によって個人の発明や創造が伝播し、新たな発明や創造が生まれることを「オートポイエーシス」と表現した。\n\nイ．サン＝シモンは、C. ダーウィンの生物進化論に基づいた社会進化論を展開した。ダーウィンが「自然選択」と呼んだものを「最適者生存」と言い換え、環境への適応の仕方の違いによって、社会は産業型社会と軍事型社会に分類されるとし、産業型社会から軍事型社会へ進化していくと主張した。\n\nウ．A. コントは、「三段階の法則（三状態の法則）」を唱え、人間の精神は「神学的―形而上学的―実証的」の三段階を経て発達するとした。そして、六つの基礎科学（数学、天文学、物理学、化学、生物学、社会学）のうち、社会学は実証的段階の最上位に位置するとした。\n\nエ．G. タルドは、『ディスタンクシオン』において、人が人に同感するのは、人類の普遍的な原理であり、その原理から社会規範が成立するとした。そして、自己認識が可能になるのは、人間が社会の中に存在しているからであり、社会の中にあることは、自分を知る「鏡」を与えられることだと述べ、「鏡に映った自我」を説いた。",
