    "question": "群集（衆）や大衆に関する学説についての記述ア～エのうち、妥当なもののみを挙げているのはどれか。\n\nア．G. ル・ボンは、『群集（衆）心理』の中で、個人は群集の中にいると、個性が消滅して同質化し、情緒性、被暗示性、無責任性、極端性などの特徴をもつ群集心理に容易に感染するようになると論じた。そして、群集について、扇動され合理的判断を失いやすい存在であるとした。\n\nイ．J. オルテガ・イ・ガセットは、『君主論』の中で、20世紀初頭のヨーロッパについて、少数のエリートによる大衆の支配が社会の不均衡をもたらしたと指摘した。そして、一定の教養を備えるに至った「大衆人」が、社会の平均人としてエリートに代わり指導的地位に上がることで、社会の均衡を目指すべきであると説いた。\n\nウ．J. F. リオタールは、『脱工業社会の到来』の中で、史的唯物論に基づき、現代社会は近代社会と連続性・一貫性を保った脱工業社会であると論じた。また、このような社会を、生産・消費の対象が有形無形を問わない最も高次の段階にあるとして、「高度大衆消費社会」とも表現した。\n\nエ．W. コーンハウザーは、『大衆社会の政治』の中で、「エリートへの接近可能性」と「非エリートの操縦可能性」を基準として四つの社会類型を析出した。このうち、エリートが非エリートの影響を被りやすく、非エリートがエリートに操縦されやすい社会を「大衆社会」とした。",
