      "ウ": "確率は標本に選ばれる可能性、回収率は調査対象者から回答が得られた割合である。偏りの少ない標本に求められる性質は代表性である。",
      "エ": "測定誤差は測定値と測ろうとする真の値のずれであり、抽出に伴うずれは標本誤差である。回収率も単純無作為抽出における選ばれ方の指標ではない。",
