    "difficulty": 3,
    "question": "次は、二つの変数の関連を分析する統計手順についての記述であるが、ア～エに当てはまるものの組合せとして最も妥当なのはどれか。\n\n以下の表は、5名の小学生A～Eに対して、英単語のテスト（10点満点）を実施し、各人における実施前一週間のテスト勉強の時間と得点を調査した結果を示したものである。この英単語のテストについて、一週間の勉強時間と得点との関連を分析したい。\n\n二つの変数の関連の指標である【ア】を求める一般的な手順は次のとおりである。\n① 各ケースの二つの変数について、それぞれの平均値からの偏差を求める。\n② 各ケースの二つの偏差の積の総和を求め、これをケース数で除し、共分散を得る。\n③ 二つの変数それぞれの標準偏差を求める。\n④ 共分散を、二つの変数の標準偏差の積で除す。\n\nこの英単語のテストについて当てはめると、まず、各人の勉強時間についてその平均値からの偏差を計算し、各人のテストの得点についてもその平均値からの偏差を計算する（①）。次に、各人において、①で得た勉強時間の偏差と得点の偏差の積を求め、その総和を人数で除す（②）。また、勉強時間の標準偏差＊とテストの得点の標準偏差＊をそれぞれ計算する（③）。最後に、②で得られた共分散の値を、③で得た二つの標準偏差の積で除すと（④）、A～Eの5名におけるこの英単語のテストの勉強時間と得点の【ア】が得られ、その値は【イ】となる。\n\n【ア】は一般に−1から【ウ】の範囲に収まるが、例えば、同じ小学生A～Eに対して漢字のテストを実施し、同様の手順で一週間の勉強時間と得点の【ア】を計算すると、−0.25となったとき、英単語のテストの場合に比べ、漢字のテストの場合は、A～Eの5名における勉強時間と得点との関連が【エ】ことが分かる。\n\n＊5名の小学生A～Eを母集団と考えたときの標準偏差",
