    "difficulty": 3,
    "question": "次の記述のA～Eに当てはまるものの組合せとして最も妥当なのはどれか。なお、解答に使用する語句は文脈に応じて斜体となるものとする。\n\nAnother example of how memory is improved by encoding is the [A] effect: Memory is better if you are asked to relate a word to yourself. Eric Leshikar and coworkers (2015) demonstrated the [A] effect by having participants in the study phase of their experiment look at a series of adjectives presented on a screen for about 3 seconds each. Examples of adjectives are loyal, happy, cultural, talkative, lazy, and conformist. There were two conditions, the [B] condition, in which participants indicated whether the adjective described themselves (yes or no), and the [C] condition, in which participants indicated whether the word was commonly used (yes or no).\n\nIn a [D] test that immediately followed the study phase, participants were presented with words from the study phase plus words that weren't presented and were told to indicate whether they remembered the words from before. The results, shown in Figure below, show that memory was better for the [B] condition than the [C] condition.\n\nWhy are participants more likely to remember words they connect to [E]? One possible explanation is that the words become linked to something the participants know well — [E]. Generally, statements that result in richer, more detailed representations in a person's mind result in better memory.",
