    "question": "視知覚に関する記述ア～エのうち、妥当なもののみを挙げているのはどれか。\n\nア．M. ウェルトハイマーは、驚き盤の観察に始まる仮現運動の実験を通じ、ゲシュタルトの考えを実証した。仮現運動とは、継時的に提示された静止対象の間に運動の印象が知覚される現象を指す。ウェルトハイマーは一連の実験において、光点の提示時間の効果を検討し、速すぎて動きが知覚されない同時時相、1光点の往復運動と知覚される最適時相、遅すぎて動きが知覚されない継時時相の運動に分類した。最適時相で知覚される仮現運動はベータ運動とも呼ばれる。\n\nイ．人の視覚認知過程のモデルには、ボトムアップアプローチとトップダウンアプローチによるものの二つがある。O. G. セルフリッジのパンデモニアム・モデルはトップダウンアプローチに基づいており、イメージデーモン、特徴デーモン、認知デーモン、決定デーモンの4種類のデーモンの分業システムが仮定されている。このモデルによると、特徴デーモンが入力された情報を特徴に分け、決定デーモンが各特徴の統合をする。\n\nウ．J. J. ギブソンによる、視覚情報についての理論である間接的知覚論に基づくと、空気中の塵や物体の表面の肌理により、光源からの放射光は散乱し、空気中で乱反射する。ゆえに、照明された環境下の動物は、空気中の全方向からの光線が交差したものに取り囲まれることになる。この動物を囲む光のことを、ギブソンは遠刺激と呼んだ。遠刺激は、動物がそれを利用するか否かにかかわらず潜在的な情報をもち、その情報を探る活動はアフォーダンスと呼ばれる。\n\nエ．G. ヨハンソンは、人の主要な関節位置に光点を取り付け、暗闇で動き始めると、静止しているときは単なる光点の集まりであったものが、光点の運動軌跡から人の運動だと知覚できることを示した。このように、人の関節位置を示す光点の情報だけで人の動きが知覚される現象をバイオロジカル・モーションという。バイオロジカル・モーションから、動作に含まれる感情や動作主体の性別などを判断できることも報告されている。",
