      "イ": "先に覚えた内容が後の学習を妨げるのは順向干渉である。後から学んだ内容が先の記憶を妨げるのは逆向干渉である。",
      "ウ": "暗算の途中結果などを保持しながら処理する機能は作業記憶である。手続き記憶は自転車の乗り方など技能の記憶を指す。",
      "エ": "維持リハーサルは反復により短期的に情報を維持する。既存知識と結び付けたり意味を付けたりして長期保持を助ける方法は精緻化リハーサルと呼ばれる。",
      "オ": "予定していた行為を時機が来たときに思い出すのが展望的記憶である。先行する刺激への接触が後続課題の処理を変える現象はプライミングである。"
