    "difficulty": 3,
    "question": "次は、E. C. トールマンが行ったラットを用いた実験研究に関する記述であるが、A～Fに当てはまるものの組合せとして最も妥当なのはどれか。ただし、Cには、㋐又は㋑のいずれかが入る。\n\nE. C. トールマンの研究グループ（1930）は、14の分岐点をもつ迷路を用いて、ラットに1日1試行の訓練を2週間以上にわたって行った。ラットは次の3群に分けられた。\n第1群…迷路の目標地点にたどり着くと常に報酬として餌が与えられた。\n第2群…迷路の目標地点にたどり着いても餌は与えられなかった。\n第3群…10日目までは【A】と同じ条件であるが、11日目以降は【B】と同じ条件であった。\n\n各試行で、ラットが袋小路に入り込んだ数が誤反応として記録された。その結果、第3群の誤反応数は、10日目までは【A】と同等のレベルで推移したが、12日目以降は急速に【B】と同等のレベルになった。\n\nこのような実験の結果を受けて、トールマンらは、ラットが10日目までに迷路内を探索することにより、【C】を形成する【D】を行ったと考え、強化は【E】には必要でないが、【F】には必要であるとした。\n\nCの候補\n㋐ 迷路の構造についての認知地図\n㋑ 刺激としての各分岐点と反応との連合",
