      "イ": "WMS-Rは、精神疾患からせん妄と認知症を鑑別する目的で作成された心理検査で、世界的に広く利用されている認知症のスクリーニング検査である。「見当識」、「記銘」、「注意と計算」、「言語」、「視覚構成」の五つの領域が11の設問で構成され、同様の検査であるデンバーIIとも相関が高く、幅広い認知機能の評価が可能である。",
      "ウ": "目標の設定や達成のための計画立案・実行など、目的のある一連の行動を有効に行うための認知機能である遂行機能（実行機能）を評価する代表的な検査に、ベンダー・ゲシュタルト・テスト（BGT）がある。この検査では、提示されたカードが色・形・数のどの基準で分けられているのかを類推させることで、遂行機能と関連が深いとされる側頭葉内側部の機能を評価する。",
      "エ": "失語症とは、脳の損傷により言語機能に異常がみられる状態をいい、損傷部位により言語機能の様々な側面に障害が現れる。日本語版WAB失語症検査の結果は、流暢性、話し言葉の理解、復唱、呼称の項目の得点から、全失語、ブローカ失語、ウェルニッケ失語、健忘失語に分類される。",
