      "イ": "DSM-5-TRによると、レビー小体型認知症は多様な精神症状とパーキンソニズムを示す疾患である。行動障害型と言語障害型があり、診断の際はいずれかの基準への適合を要するが、多数の人が両方の特徴を示す。行動障害型は、行動の脱抑制や無気力の症状を呈したり、自己管理及び自己責任に対する関心を失ったり、社会的不適切行動を示す。認知症全体におけるレビー小体型の出現頻度はアルツハイマー型と同程度であるとされている。",
      "ウ": "心身症とは、身体疾患の中で、その発症や経過に心理社会的因子が密接に関与し、器質的ないし機能的障害が認められる病態をいう。ただし、神経症やうつ病など、他の精神障害に伴う身体症状は除外される。心身症とみなされることがある身体疾患の例として、潰瘍性大腸炎、気管支ぜんそく、狭心症、片頭痛などが挙げられる。治療法として、リラクセーション法の一つである自律訓練法などがある。",
