      "オ": "双極症には、抑うつエピソードと軽躁エピソードが反復して生じる双極症Ⅰ型と、躁エピソードの存在を中核とする双極症Ⅱ型がある。いずれの型においても、抑うつエピソードよりも躁あるいは軽躁のエピソード期間が長いことが特徴である。また、1年以内に4回以上の躁、軽躁又は抑うつエピソードの基準を満たすエピソードが認められる場合を急速交代型（ラピッドサイクラー）という。"
