    "question": "次は、諸外国における教育制度に関する記述であるが、A～Dに該当する国名の組合せとして最も妥当なのはどれか。なお、データは文部科学省の『諸外国の教育統計 令和6（2024）年版』による。\n\nA．主として義務教育は9年で、そのうち初等教育は基礎学校で4年間行われる。前期中等教育段階から、大学進学を目指す者が主に進む学校種、職業教育学校への進学や中級の職への就職を目指す者が主に進む学校種、卒業後就職して職業訓練に入る者が主に進む学校種の三つに分岐する伝統的な形態が存在するほか、近年、総合的な教育課程を備えた総合制学校も設けられている。\n\nB．義務教育は3歳から16歳までの13年とされており、そのうち初等教育は小学校で5年間行われる。前期中等教育段階の4年間の観察・進路指導の結果に基づいて、生徒は後期中等教育の諸学校・課程に振り分けられ、高等教育機関に入学するには、原則として、中等教育修了と高等教育入学資格を合わせて認定するバカロレアを取得しなければならないとされている。\n\nC．義務教育は5歳から16歳までの11年とされており、そのうち初等教育は一般的に6年制の初等学校で行われる。前期中等教育は、原則無選抜のコンプリヘンシブ・スクールの形態が一般的であるが、選抜制のグラマー・スクールやモダン・スクールなどに振り分ける地域も一部にある。後期中等教育の課程・機関には、中等学校に設置されているシックスフォームと呼ばれる課程や独立の学校として設置されているシックスフォーム・カレッジがある。\n\nD．義務教育は6歳から15歳までの9年とされており、そのうち初等教育は初等学校で6年間行われる。前期中等教育は、中学校で3年間行われ、後期中等教育機関には、普通教育を中心とする教育課程を提供する普通高等学校と職業教育を提供する職業高等学校があり、普通高等学校には各分野の才能がある者を対象とした高等学校も含まれている。",
