    "question": "状況論的アプローチに基づく学習に関する記述として最も妥当なのはどれか。",
    "choices": {
      "ア": "実践共同体の正式なメンバーとして実際の活動に参加し、参加の形態を徐々に変化させながら、より深く実践共同体の活動に関与するようになる過程を正統的周辺参加という。そこでは、実践への参加の仕方が、十全的な参加から正統的かつ周辺的な参加へと変化する。この考えに基づくと、子どもが経験する練習や訓練の結果として、比較的永続的な、客観的に観察可能な行動上の変化が生じることが学習とみなされる。",
      "イ": "経験の浅い者が熟達者の指導の下で知識やスキルを獲得する、社会的相互作用による学習方法をティームティーチングという。この方法は、熟達者によって最終目標に至るまでの下位目標が難易度順に段階的に配列され、学習者はそれらを一段階ずつ漸進的に学習を進めていくこと、学習者による反応がなされた場合に初めて強化が与えられること、学習者が問題に答えると直ちにその正誤が知らされることなどを特徴とする。",
      "ウ": "知的作業の社会的実践が、制度的分業体制や各種の道具・テクノロジー、成員間のコミュニケーションなどから構成される状況との相互作用システムの中で生じるという考え方を、状況的行為という。この視点によれば、人間は、発達早期から対象の認知に際して働かせる認知構造をもっており、新奇な状況に際して、その認知構造に新しい情報や経験を組み込んで対象を理解しようとしたり、また自身の認知構造を変容させることで対象を理解したりする。",
      "エ": "認識は、個人の頭という閉じた系の中にあるのではなく、他者と相互作用し合い、協同活動する過程の中で生じる現象と捉える考え方を、身体化された認知という。この考え方では、はじめは他者の中にあった知識が、他者、特に習熟した大人との相互作用によって個人の内部に取り込まれ、しだいに自己のものとして内化される過程を思考や認識の発達と捉える。その相互作用の過程においては、先行オーガナイザーの働きが重要視される。",
      "オ": "近代の学校教育制度における学校での学びは、現実とは切り離された抽象的な「学校知」の獲得に偏っていると指摘されることがあり、中でも、学校という文脈を離れた日常生活との乖離が問題視されてきた。これに対し、普及したインターネットを活用する「分散化された学習環境」が提唱された。これは、学習の場を学校に限らず、インターネット等を活用することにより、学校の枠を超えてある種の具体的な認知的実践に学習者を参加させる学習環境を指す。"
    },
