      "イ": "身体障害者補助犬法は、補助犬の育成及び補助犬使用者の施設等の利用の円滑化を図り、身体障害者の自立及び社会参加の促進に寄与することを目的としている。同法において、身体障害者補助犬とは盲導犬及び介助犬の二種と定義されている。また、国等の事業所又は事務所並びに民間事業所の事業主は、その規模にかかわらず、勤務する身体障害者の補助犬の使用を拒んではならないと規定されており、これに違反した場合の罰則規定も設けられている。",
      "ウ": "バリアフリー法＊1は、その基本理念として、同法に基づく措置が社会的障壁の除去及び共生社会の実現に資することを旨として行われなければならない旨規定している。同法において、公共交通事業者等は、新設旅客施設等を公共交通移動等円滑化基準に適合させ、また同基準に適合するように維持するとともに、当該新設旅客施設等を使用した役務の提供の方法に関する基準（ソフト基準）を遵守しなければならないとされている。",
