    "question": "近代（モダニティ）に関する学説についての記述ア～エのうち、妥当なもののみを全て挙げているのはどれか。\n\nア．M. ヴェーバーは、ある社会の特性をパターン変数（型の変数）によって捉えられるとし、西洋近代社会は、感情中立性に対する感情性、集団志向に対する自己志向、個別主義に対する普遍主義、業績本位に対する属性本位、無限定性に対する限定性によって特徴付けられる社会とみなし、中でも西洋近代の母体となった宗教としてのプロテスタンティズム教団の合理性を普遍主義と属性本位に求めた。\n\nイ．V. パレートは、共有されたシンボル体系が人間行動の社会的進化の分析にとって重要な役割を果たすという見方に立ち、近代化という社会進化の過程は、（1）価値の一般化、（2）包摂、⑶適応能力の上昇、⑷分化という四つのプロセスを経由する中で、信念と力をもったエリートが知的柔軟性と革新性をもった指導者に不可逆的に進化することによって実現すると考えた。\n\nウ．A. ギデンズは、ポストモダニティの社会理論が、モダニティの徹底化によってモダニティの解体がもたらされると主張するのに対し、モダニティの徹底化はむしろモダニティの特質を純化するという立場から、ハイ・モダニティ論を展開し、モダニティの特徴を時間と空間の分離、脱埋め込み化（伝統から意識や制度の離脱）、リフレクシヴィティ（意味の問い直し）の増大に求めた。\n\nエ．M. フーコーは、「精神の病」にみられるような正常と病理の区別が、近代以前にも存在する普遍的な概念であることを歴史資料に基づいて明らかにする一方、思想的には J.P. サルトルの実存主義の立場からレヴィ = ストロースの構造人類学を批判し、伝統的な共同体規範に代わる近代的主体とヒューマニズムへの信仰によって更なる近代化を推し進めるべきであると主張した。",
