    "question": "次は、グローバリゼーションに関する理論についての記述を抜粋（一部省略）したものであるが、A～Eに当てはまるものの組合せとして最も妥当なのはどれか。ただし、解答に使用する語句は文脈に応じて斜体となるものとする。なお、文中の［伏字］については設問の都合上伏せてある。\n\nBefore the 1970s, social scientists tended to discuss the world's societies in terms of First, Second and Third worlds, based on their levels of [A] enterprise, industrialization and urbanization. The solution to Third World ‘underdevelopment’ was therefore thought to be more ［伏字］, more industry and more urbanization. [B] rejected this dominant way of categorizing societies, arguing instead that there is one world economy and that all the societies within it are connected by [A] economic relationships. He described this complex intertwining of economies as the ‘modern world-system’, which was a pioneer of today’s globalization theories.\n\n《中略》\n\nThe origins of the modern world-system lie in sixteenth- and seventeenth-century Europe, where [C] enabled countries such as Britain, Holland and France to exploit the resources of the countries they [D]. This allowed them to accumulate ［伏字］, which was ploughed back into their economy, driving forward production and development. This global division of labour created a group of rich countries but impoverished many others, thus stunting their development. [B] argues that the process produced a world-system made up of a [E], a periphery and a semi-periphery. And although it is clearly possible for individual countries to move ‘up’ into the [E] or to drop ‘down’ into the semi-periphery and periphery, the basic structure of the modern world-system remains constant.",
