    "question": "自己やアイデンティティ形成に関する学説についての記述ア～エのうち、妥当なもののみを全て挙げているのはどれか。\n\nア．G.H. ミードは、社会的相互作用による自己の形成について考察した。彼は、自己形成を、他者の反応や態度を取得し、それを自己に取り入れる過程と捉えた。自己は「インフォーマルな集団」の反応や態度を学ぶ段階から、「フォーマルな集団」の反応や態度を学ぶ段階へと移行する。そうすることによって、自己は社会の一員として自らの役割を理解し、状況の変化に左右されない確固とした「超自我」が形成されると考えた。\n\nイ．E.H. エリクソンは、人間の欲求を五つの段階に分ける欲求論を展開した。彼によれば、人間としての基礎的な欲求である生理的欲求や安全欲求がある程度満たされると、所属と愛情の欲求、他者承認の欲求が満たされ、最後に自己実現の欲求が出現するようになるという。その中で、欲望が際限なく肥大化する「集合的沸騰」の危険性を指描した。\n\nウ．W. リップマンは、第二次世界大戦後の米国における消費社会化に対応する性格構造として「内部指向」という概念を提起した。内部指向とは、工場労働のようなモノを対象にした生産活動に従事する人々が減少し、ホワイトカラーのように人を対象にした労働に従事する人々が増加していく中で、他人の動向に敏感に対応しながら、自らの行為を選択するような人格を表し、そのような人格が消費社会に適合的になってきていると主張した。\n\nエ．A. ホネットは、個人の自己実現において「社会的承認」が不可欠であると主張した。彼は、社会的承認の主要な形態を、家族や恋人、親しい友人からの愛情による承認、法（権利）関係によって平等な個人として尊重される承認、価値共同体における貢献や能力が評価されることによる承認の三つに分類し、個人の自己実現は、他者からの承認によって形成される肯定的な自己関係によって可能になるとした。",
