    "question": "自己の表出に関する記述ア～エのうち、妥当なもののみを挙げているのはどれか。\n\nア．自己の姿を表出する行為として、自己開示と自己呈示がある。他者に対して、言語を介して自分自身に関する情報を伝達する行為は、自己開示と呼ばれる。自己開示が主として言語的な伝達を対象としているのに対して、自己呈示は、言語的な伝達だけでなく、非言語的な伝達も含んでいる。\n\nイ．I. アルトマンと D.A. テイラーによって提唱された社会的浸透理論とは、集団における多数派が少数派に影響を及ぼす過程を分析したものである。この理論によれば、多数派による意見の表明が少数派に影響を及ぼす過程では自律性や一貫性、堅固さ、公正さなどが必要とされ、少数派に多数派の意見が浸透して態度変容に至るまでには時間が掛かるという。\n\nウ．自己呈示の一つであるセルフ・ハンディキャッピングとは、ある課題を遂行する際に、その遂行結果の評価を明確にするために、課題遂行の妨害となる障害を自ら作り出すことをいう。セルフ・ハンディキャッピングは、自ら不利な状況を作り出す主張的セルフ・ハンディキャッピングと不利な状況にあることを訴える獲得的セルフ・ハンディキャッピングとに大別される。\n\nエ．E.E. ジョーンズと T. S. ピットマンは、主張的自己呈示を目標の違いから「取り入り」、「自己宣伝」、「示範」、「威嚇」、「哀願」の五つに整理した。自己にとって望ましい結果を得るために、「取り入り」、「自己宣伝」、「示範」は肯定的な印象を、「威嚇」、「哀願」 は否定的な印象を他者に与えようとする自己呈示である。",
