      "イ": "自己拡張モデルでは、親密な相手の視点や資源を自分の一部として取り込むと考える。アは単に繰り返し接する効果に言語的交流を必須とする点が誤っている。",
      "ウ": "単純接触効果は接触を繰り返すこと自体と好意の変化の関係を扱う。自己カテゴリー化理論はターナーらの理論であり、マースタインによる親密関係の理論とは異なる。",
      "エ": "シボーとケリーは、関係から得る報酬と付随するコストから成果を捉えた。アロンらのIOS尺度は、二つの円が重なる程度を選ばせて、自他を重ね合わせる感覚を測る。",
      "オ": "ウの自己拡張モデルは妥当である。メタ・コントラスト比は、類似・相違に基づくカテゴリー化の考え方に結び付き、マースタインの親密な関係の理論としては扱わない。"
