    "question": "自殺に関する記述ア～エのうち、妥当なもののみを全て挙げているのはどれか。\n\nア．D. ベルは、『危険社会』において、近代化の失敗によってグローバル規模で生命を危険にさらす人工的な災害、例えば原発事故や地球温暖化などが生じるようになったと主張し、これらの災害の脅威にさらされた人々は自殺のリスクが高まることを、統計資料の詳細な分析から明らかにした。\n\nイ．E. デュルケムは、『自殺論』において、社会に原因が求められる自殺として、自己本位的自殺、集団本位的自殺、アノミー的自殺、宿命的自殺を指摘している。社会的規制が過度に弱い状態はアノミーと呼ばれ、人々の欲望が社会によって規制されていない状態を意味し、アノミー的自殺は、このような状況下で発生するとしている。\n\nウ．「令和5年版自殺対策白書」によると、令和4年の我が国の自殺者数は3万人を超えており、前年と同水準となっている。男女別に自殺者数をみると、女性の方が男性よりも多く、約2倍となっている。職業別にみると、総数では「無職者」が最も多く、原因・動機別にみると、総数では「経済・生活問題」が最も多く、次に「家庭問題」が続いている。\n\nエ．我が国では、総合的な自殺対策を推進するため、平成18年に自殺対策基本法が制定された。令和4年には第4次自殺総合対策大綱が閣議決定され、コロナ禍の自殺動向も踏まえつつ、これまでの取組の充実に加えて、①子ども・若者の自殺対策の更なる推進・強化、②女性に対する支援の強化、③地域自殺対策の取組強化、④総合的な自殺対策の更なる推進・強化の四つの柱に取り組むこととされている。",
